import math
import sys

class Point:
    def __init__(self, x, y):
        self.x = x
        self.y = y

    def __str__(self):
        return f"({self.x},{self.y})"

    def sub(self, other):
        return Point(self.x - other.x, self.y - other.y)

    def move_along_line(self, line, length):
        return self.move_along_vector(line.as_vector(), length)

    def move_along_vector(self, vec, length):
        mag = math.sqrt(vec.x * vec.x + vec.y * vec.y)
        if mag < 1e-15:
            return Point(self.x, self.y)
        return self.add(Point(vec.x / mag, vec.y / mag).mul(length))

    def add(self, other):
        return Point(self.x + other.x, self.y + other.y)

    def mul(self, f):
        return Point(self.x * f, self.y * f)

    def normalize(self):
        length = math.sqrt(self.x * self.x + self.y * self.y)
        return self.div(length)

    def div(self, f):
        return Point(self.x / f, self.y / f)

    def get_alpha(self):
        return Point(-self.y, self.x)

    def __eq__(self, other):
        if not isinstance(other, Point):
            return False
        return abs(self.x - other.x) < 1e-10 and abs(self.y - other.y) < 1e-10

    def __lt__(self, o):
        if abs(self.x - o.x) < 1e-10:
            return self.y < o.y
        return self.x < o.x

class Line:
    def __init__(self, from_point, to_point):
        self.from_point = from_point
        self.to_point = to_point

    def as_vector(self):
        return self.to_point.sub(self.from_point)

    def length(self):
        return math.hypot(self.to_point.x - self.from_point.x, self.to_point.y - self.from_point.y)

class Circle:
    def __init__(self, x, y, r):
        self.center = Point(x, y)
        self.r = r

    @staticmethod
    def is_intersect(a, b):
        d = distance(a.center, b.center)
        return d <= a.r + b.r + 1e-10 and d + 1e-10 >= abs(a.r - b.r)

    @staticmethod
    def is_intersect2(a, b):
        d = distance(a.center, b.center)
        return d < a.r + b.r and d > abs(a.r - b.r)

    @staticmethod
    def intersect_at(a, b, set_points):
        if not Circle.is_intersect(a, b):
            return
        line = Line(a.center, b.center)
        d = distance(a.center, b.center)
        middle_distance = (d * d - b.r * b.r + a.r * a.r) / (2 * d)
        middle = a.center.move_along_line(line, middle_distance)
        alpha = line.as_vector().get_alpha()
        height = math.sqrt(a.r * a.r - middle_distance * middle_distance)
        first = middle.move_along_vector(alpha, height)
        second = middle.move_along_vector(alpha, -height)
        set_points.add(first)
        if not second == first:
            set_points.add(second)

def distance(a, b):
    return math.hypot(a.x - b.x, a.y - b.y)

def main():
    input_data = sys.stdin.read().strip().split()
    n = int(input_data[0])
    circles = []
    index = 1
    for _ in range(n):
        x = int(input_data[index])
        y = int(input_data[index + 1])
        r = int(input_data[index + 2])
        index += 3
        circles.append(Circle(x, y, r))
    if n == 3 and not Circle.is_intersect(circles[0], circles[1]):
        sum_value = 4
        if Circle.is_intersect2(circles[0], circles[2]):
            sum_value += 1
        if Circle.is_intersect2(circles[1], circles[2]):
            sum_value += 1
        print(sum_value)
        return
    total = 1
    set_points = set()
    for i in range(n):
        set_points.clear()
        total += 1
        for j in range(i):
            Circle.intersect_at(circles[i], circles[j], set_points)
        if len(set_points) >= 2:
            total += len(set_points) - 1
    print(total)

if __name__ == "__main__":
    main()

